G = nx.Graph()
for i in range(21):
    G.add_node(i)
for i in range(21):
    for j in range(i+1, 21):
        if len(list(G.neighbors(i))) < 6 and len(list(G.neighbors(j))) < 6:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 6 or len(list(G.neighbors(j))) == 6:
                break
if min(list(nx.shortest_path_length(G, source=i, target=j) for i in range(21) for j in range(i+1, 21) if nx.has_path(G, source=i, target=j))) >= 7 and all(3 <= len(list(G.neighbors(i))) <= 6 for i in range(21)):
    print("SATISFIABLE")
